func:
// Decouverte automatique du portal ID (VRM) a partir du topic
// N/<portal_id>/system/0/Serial (message retenu par le broker du Cerbo).
const parts = msg.topic.split('/');
if (parts.length < 2 || !parts[1]) { return null; }
const id = parts[1];
const prev = global.get('haku_portal_id', 'file');
global.set('haku_portal_id', id, 'file');
node.status({ fill: 'green', shape: 'dot', text: 'portal: ' + id });
const info = { payload: id, topic: 'portal_id' };
if (prev !== id) {
    // Nouveau portal ID : declencher immediatement un keepalive "full publish".
    return [info, { force_full: true }];
}
return [info, null];

// Keepalive dbus-flashmq (Venus OS >= 3.x) : sans lui les topics N/...
// cessent d'etre publies au bout de 60 s. On publie toutes les 30 s sur
// R/<portal_id>/keepalive :
//  - payload vide            -> republication complete de tous les topics
//  - {"keepalive-options":["suppress-republish"]} -> keepalive silencieux
// Strategie : 1er envoi (et resynchro ~10 min) en "full", le reste en silencieux.
const id = global.get('haku_portal_id', 'file');
if (!id) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'portal ID inconnu (attente Serial)' });
    return null;
}
const n = (context.get('count') || 0) + 1;
context.set('count', n);
const full = (msg.force_full === true) || (n === 1) || (n % 20 === 0);
const out = { topic: 'R/' + id + '/keepalive' };
out.payload = full ? '' : JSON.stringify({ 'keepalive-options': ['suppress-republish'] });
node.status({ fill: 'blue', shape: 'dot', text: (full ? 'full ' : '') + 'keepalive #' + n });
return out;

// Parsing generique des topics Victron N/<portal>/<service>/<instance>/<chemin>
// Payload dbus-flashmq : {"value": ...} (value=null => donnee invalide, ignoree).
// Sortie : { topic: <cle interne>, payload: <valeur> } + mise a jour du cache global.
let v;
try {
    if (msg.payload === '' || msg.payload === null) { return null; } // appareil disparu
    const p = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
    v = p.value;
} catch (e) { return null; }
if (v === null || v === undefined) { return null; }
const t = msg.topic.split('/');
if (t.length < 5) { return null; }
const service = t[2];
const path = t.slice(4).join('/');
let key = null;
if (service === 'system') {
    switch (path) {
        case 'Dc/Battery/Soc': key = 'soc'; break;
        case 'Dc/Battery/Voltage': key = 'voltage'; break;
        case 'Dc/Battery/Current': key = 'current'; break;
        case 'Dc/Battery/Power': key = 'power'; break;
        case 'Dc/Battery/Temperature': key = 'temperature'; break;
        case 'Dc/Pv/Power': key = 'pv_power'; break;
        case 'Dc/System/Power': key = 'dc_load'; break;
        case 'Ac/ActiveIn/Source': key = 'ac_source'; break;
        case 'SystemState/State': key = 'sys_state'; break;
        default:
            // Relais : feu de mouillage (RELAY_DBUS_INDEX, 0 = borne "Relay 1"),
            // puis, selon WAVESHARE_ENABLED, l'affectation de la borne "Relay 2" :
            //  - 0 (v1.1) : relais instruments Cerbo (INSTR_RELAY_INDEX) ;
            //  - 1 (v1.2) : eclairage exterieur / spreader lights
            //    (RELAY_LIGHT_INDEX) — les instruments passent sur le relais 1
            //    du module Waveshare.
            // Decalage borne/index a verifier a bord (README §6).
            if (/^Relay\/\d+\/State$/.test(path)) {
                const idx = path.split('/')[1];
                const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
                if (idx === String(env.get('RELAY_DBUS_INDEX') || '0')) {
                    key = 'relay_state';
                } else if (wsOn && idx === String(env.get('RELAY_LIGHT_INDEX') || '1')) {
                    key = 'relay_light';
                } else if (!wsOn && idx === String(env.get('INSTR_RELAY_INDEX') || '1')) {
                    key = 'relay_instr';
                }
            }
    }
} else if (service === 'vebus' && path === 'Ac/ActiveIn/Connected') {
    key = 'ac_connected'; // present uniquement quand le Quattro sera installe
}
if (key === null) { return null; }
const num = Number(v);
const val = isNaN(num) ? v : num;
const data = global.get('haku_data') || {};
data[key] = { v: val, ts: Date.now() };
global.set('haku_data', data);
global.set('haku_last_msg_ts', Date.now());
return { topic: key, payload: val };

// Etat de la connexion MQTT (alimente par un noeud status).
const txt = String((msg.status && msg.status.text) || '');
let label = 'Inconnu';
let ok = false;
if (/disconnected|connect\.failed|lost/i.test(txt)) { label = 'Deconnecte'; }
else if (/connecting/i.test(txt)) { label = 'Connexion...'; }
else if (/connected/i.test(txt)) { label = 'Connecte'; ok = true; }
global.set('haku_mqtt_ok', ok);
return { payload: label, topic: 'mqtt_status' };

// Journalisation centralisee des erreurs de flux (visible via journalctl).
const c = (global.get('haku_error_count') || 0) + 1;
global.set('haku_error_count', c);
const src = (msg.error && msg.error.source && msg.error.source.name) || 'inconnu';
node.warn('Erreur flux #' + c + ' [' + src + '] : ' +
    ((msg.error && msg.error.message) || 'sans message'));
return null;

// Convention Victron : courant > 0 = charge de la batterie, < 0 = decharge.
const c = Number(msg.payload);
msg.payload = (c > 0 ? '+' : '') + c.toFixed(1);
return msg;

// /Ac/ActiveIn/Source : 0=indisponible, 1=reseau, 2=generateur, 3=quai,
// 240=inverter (aucune entree AC). Absent tant qu'aucun Quattro n'est installe.
const map = { 0: 'Indisponible', 1: 'Reseau (grid)', 2: 'Generateur', 3: 'QUAI (shore)', 240: 'ABSENTE (inverter)' };
const v = Number(msg.payload);
const label = (map[v] !== undefined) ? map[v] : ('Inconnue (' + msg.payload + ')');
if (context.get('prev') !== v) {
    context.set('prev', v);
    context.set('since', Date.now());
}
const since = context.get('since');
const tz = env.get('TZ') || 'Europe/Paris';
const sinceTxt = since ? new Date(since).toLocaleString('fr-FR', { timeZone: tz }) : '-';
return [{ payload: label }, { payload: sinceTxt }];

// /SystemState/State (com.victronenergy.system)
const map = {
    0: 'Arret', 1: 'Basse conso', 2: 'Defaut VE.Bus', 3: 'Bulk', 4: 'Absorption',
    5: 'Float', 6: 'Stockage', 7: 'Egalisation', 8: 'Passthru', 9: 'Inverter',
    10: 'Assistance', 244: 'Maintien batterie', 252: 'Controle externe',
    256: 'Decharge', 257: 'Sustain', 258: 'Recharge', 259: 'Recharge programmee'
};
const v = Number(msg.payload);
msg.payload = (map[v] !== undefined) ? map[v] : ('Etat ' + msg.payload);
return msg;

// Age de la derniere donnee MQTT + liste des alertes actives.
const last = global.get('haku_last_msg_ts');
let ageTxt;
if (!last) { ageTxt = 'aucune donnee recue'; }
else {
    const s = Math.round((Date.now() - last) / 1000);
    ageTxt = (s < 90) ? ('il y a ' + s + ' s') : ('il y a ' + Math.round(s / 60) + ' min');
}
const alerts = global.get('haku_active_alerts') || [];
const aTxt = alerts.length ? alerts.join(' | ') : 'Aucune';
return [{ payload: ageTxt }, { payload: aTxt }];

// Position du soleil (algorithme NOAA/Meeus simplifie, precision < 0,2 deg).
// Suffisant pour une bascule feu de mouillage : bascule a l'elevation
// SUN_NIGHT_ELEV (defaut -0,833 deg = coucher/lever officiel, refraction incluse).
const lat = parseFloat(env.get('HAKU_LAT') || '43.27');
const lon = parseFloat(env.get('HAKU_LON') || '5.35');
const rad = Math.PI / 180;
const now = new Date();
const jd = now.getTime() / 86400000 + 2440587.5;   // jour julien
const n = jd - 2451545.0;                           // jours depuis J2000
const L = (280.460 + 0.9856474 * n) % 360;          // longitude moyenne
const g = ((357.528 + 0.9856003 * n) % 360) * rad;  // anomalie moyenne
const lambda = (L + 1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g)) * rad;
const eps = (23.439 - 0.0000004 * n) * rad;         // obliquite
const alpha = Math.atan2(Math.cos(eps) * Math.sin(lambda), Math.cos(lambda));
const delta = Math.asin(Math.sin(eps) * Math.sin(lambda));
const gmst = (280.46061837 + 360.98564736629 * n) % 360; // temps sideral Greenwich
const lha = ((gmst + lon) * rad) - alpha;           // angle horaire local
let sinElev = Math.sin(lat * rad) * Math.sin(delta) +
              Math.cos(lat * rad) * Math.cos(delta) * Math.cos(lha);
sinElev = Math.max(-1, Math.min(1, sinElev));
const elev = Math.asin(sinElev) / rad;
const nightElev = parseFloat(env.get('SUN_NIGHT_ELEV') || '-0.833');
msg.elevation = Math.round(elev * 10) / 10;
msg.isNight = elev < nightElev;
msg.payload = msg.isNight ? 'nuit' : 'jour';
global.set('haku_sun', { elevation: msg.elevation, isNight: msg.isNight, ts: Date.now() });
return msg;

// Relit le mode persiste au demarrage (defaut : MARINA, feu verrouille).
msg.payload = global.get('haku_mode', 'file') || 'MARINA';
msg.restore = true;
return msg;

// Persistance du mode MOUILLAGE/MARINA (context store 'file' -> survit au reboot).
let mode = msg.payload;
if (mode !== 'MOUILLAGE' && mode !== 'MARINA') { mode = 'MARINA'; }
global.set('haku_mode', mode, 'file');
node.status({ fill: (mode === 'MARINA') ? 'grey' : 'yellow', shape: 'dot', text: mode });
const confirm = { payload: mode };
const evaluate = { payload: mode, topic: 'mode' };
// v1.3 : le Pi n'ecrit plus sur le relais du feu. Ce mode ne pilote plus rien
// tant que le canal de MODE vers le Cerbo n'est pas en place : la notification
// ne doit donc plus laisser croire a un verrouillage.
const notif = (msg.restore === true) ? null
    : { payload: 'Mode Pi : ' + mode + ' — sans effet sur le feu, le Cerbo en est seul maitre' };
return [confirm, evaluate, notif];

// v1.3 — LE PI N'ECRIT PLUS SUR LE RELAIS DU FEU DE MOUILLAGE.
// Le flux « Feu v3 » du Cerbo est desormais seul maitre : sa logique est
// complete (nuit -30 min + hors port + immobile) et elle tourne meme Pi
// eteint. Ce noeud ne fait plus qu'AFFICHER. Sortie 1 toujours nulle.
// Retablir une commande depuis le Pi passera par un canal de MODE cote
// Cerbo (AUTO / FORCE ON), jamais par une ecriture directe du relais.
const mode = global.get('haku_mode', 'file') || 'MARINA';
const sun = global.get('haku_sun') || { isNight: false, elevation: null };
const data = global.get('haku_data') || {};
const actual = (data.relay_state !== undefined) ? Number(data.relay_state.v) : null;
const mqttOk = global.get('haku_mqtt_ok') === true;
let etat;
if (!mqttOk || actual === null) {
    etat = 'Cerbo injoignable - etat du feu inconnu';
    node.status({ fill: 'grey', shape: 'ring', text: 'Cerbo injoignable' });
} else {
    etat = actual === 1 ? 'Feu ALLUME (decide par le Cerbo)' : 'Feu eteint (decide par le Cerbo)';
    node.status({ fill: actual === 1 ? 'green' : 'grey', shape: 'dot',
                  text: (actual === 1 ? 'ALLUME' : 'eteint') + ' - maitre : Cerbo' });
}
etat += ' | mode Pi : ' + mode + (sun.isNight ? ', nuit' : ', jour');
return [null, { payload: etat, topic: 'feu_etat' }];

// ====================== Moteur d'alertes Haku ======================
// Appele sur chaque donnee (tab 1) et par un tick de 60 s.
// Etats persistants dans le context store 'file' (survivent au reboot).
const cfg = {
    socMin:   parseFloat(env.get('ALERT_SOC_MIN') || '30'),
    vMin:     parseFloat(env.get('ALERT_VBAT_MIN') || '24.8'),
    tMax:     parseFloat(env.get('ALERT_TBAT_MAX') || '45'),
    acLoss:   parseFloat(env.get('ALERT_AC_LOSS_MIN') || '5'),
    fullV:    parseFloat(env.get('FULLCHARGE_V') || '28.4'),
    fullHold: parseFloat(env.get('FULLCHARGE_HOLD_MIN') || '10'),
    fullDays: parseFloat(env.get('FULLCHARGE_MAX_DAYS') || '14'),
    cerboMin: parseFloat(env.get('CERBO_TIMEOUT_MIN') || '15'),
    remindH:  parseFloat(env.get('ALERT_REMIND_H') || '24')
};
const now = Date.now();
const data = global.get('haku_data') || {};
const st = context.get('st', 'file') || {};
const val = k => (data[k] !== undefined ? Number(data[k].v) : null);
const fresh = (k, min) => (data[k] !== undefined && (now - data[k].ts) < (min || 12) * 60000);
const out = [];

function raise(key, label, subject, body) {
    const s = st[key] = st[key] || {};
    if (!s.active) { s.active = true; s.since = now; s.lastSent = 0; }
    s.label = label;
    if (now - (s.lastSent || 0) >= cfg.remindH * 3600000) {
        s.lastSent = now;
        out.push({ key: key, subject: subject, body: body });
    }
}
function clearA(key, recovered) {
    const s = st[key];
    if (s && s.active) {
        s.active = false;
        if (recovered) { out.push({ key: key + '_ok', subject: recovered.s, body: recovered.b }); }
    }
}

// 1. SOC bas (hysteresis +5 points)
const soc = val('soc');
if (soc !== null && fresh('soc')) {
    if (soc < cfg.socMin) {
        raise('soc', 'SOC bas',
            'Haku : SOC batterie bas (' + soc.toFixed(0) + ' %)',
            'SOC descendu a ' + soc.toFixed(1) + ' % (seuil ' + cfg.socMin + ' %). Parc LiFePO4 24 V / 920 Ah.');
    } else if (soc > cfg.socMin + 5) { clearA('soc'); }
}
// 2. Tension basse (hysteresis +0,3 V)
const v = val('voltage');
if (v !== null && fresh('voltage')) {
    if (v < cfg.vMin) {
        raise('vbat', 'Tension basse',
            'Haku : tension batterie basse (' + v.toFixed(2) + ' V)',
            'Tension mesuree ' + v.toFixed(2) + ' V (seuil ' + cfg.vMin + ' V).');
    } else if (v > cfg.vMin + 0.3) { clearA('vbat'); }
}
// 3. Temperature batterie haute (hysteresis -3 degC)
const t = val('temperature');
if (t !== null && fresh('temperature')) {
    if (t > cfg.tMax) {
        raise('tbat', 'Temperature batterie haute',
            'Haku : temperature batterie ' + t.toFixed(1) + ' °C',
            'Temperature batterie ' + t.toFixed(1) + ' °C (seuil ' + cfg.tMax + ' °C). Verifier charge et ventilation.');
    } else if (t < cfg.tMax - 3) { clearA('tbat'); }
}
// 4. Perte du quai : source AC active absente > N min (1=reseau, 3=quai).
//    Ne s'arme qu'apres avoir vu le quai present au moins une fois (evite les
//    fausses alertes tant que le Quattro n'est pas installe : topic absent).
const src = fresh('ac_source', 30) ? val('ac_source') : null;
const ac = st.ac = st.ac || {};
if (src !== null) {
    const present = (src === 1 || src === 3);
    if (present) { ac.everPresent = true; ac.absentSince = null; }
    else if (ac.everPresent && !ac.absentSince) { ac.absentSince = now; }
    if (ac.everPresent && ac.absentSince && (now - ac.absentSince) > cfg.acLoss * 60000) {
        raise('ac_loss', 'Quai perdu',
            'Haku : PERTE DU QUAI',
            'Entr\u00e9e AC absente depuis plus de ' + cfg.acLoss + ' min (source=' + src + '). Le bord tourne sur batteries.');
    } else if (present) {
        clearA('ac_loss', { s: 'Haku : quai retabli', b: 'L alimentation de quai est revenue.' });
    }
}
// 5. Pas de pleine charge (>= FULLCHARGE_V tenue FULLCHARGE_HOLD_MIN) depuis N jours.
const fc = st.fc = st.fc || {};
if (!fc.ref) { fc.ref = now; }  // reference posee a la premiere execution
if (v !== null && fresh('voltage')) {
    if (v >= cfg.fullV) {
        if (!fc.holdStart) { fc.holdStart = now; }
        if (now - fc.holdStart >= cfg.fullHold * 60000) { fc.lastFull = now; }
    } else { fc.holdStart = null; }
}
const refFull = Math.max(fc.lastFull || 0, fc.ref);
const daysSince = (now - refFull) / 86400000;
if (daysSince > cfg.fullDays) {
    raise('fullcharge', 'Pleine charge en retard',
        'Haku : pas de pleine charge depuis ' + Math.floor(daysSince) + ' j',
        'Aucune tenue >= ' + cfg.fullV + ' V pendant ' + cfg.fullHold + ' min depuis ' +
        Math.floor(daysSince) + ' jours (max ' + cfg.fullDays +
        '). Resynchronisation SOC / equilibrage recommandes (plan batteries du bord).');
} else if (fc.lastFull && daysSince < 1) { clearA('fullcharge'); }
// 6. Cerbo silencieux (aucun message MQTT depuis N min).
//    Reference de repli : l'heure de demarrage de Node-RED (contexte memoire),
//    pour que l'alerte parte aussi si le Cerbo est muet DES le boot.
let lastMsg = global.get('haku_last_msg_ts') || null;
if (!lastMsg) {
    let bootTs = context.get('boot_ts');
    if (!bootTs) { bootTs = now; context.set('boot_ts', bootTs); }
    lastMsg = bootTs;
}
if (lastMsg) {
    if (now - lastMsg > cfg.cerboMin * 60000) {
        raise('cerbo', 'Cerbo injoignable',
            'Haku : Cerbo GX injoignable',
            'Aucune donnee MQTT du Cerbo depuis plus de ' + cfg.cerboMin + ' min. Verifier le reseau du bord et le Cerbo.');
    } else {
        clearA('cerbo', { s: 'Haku : Cerbo de retour', b: 'Les donnees MQTT du Cerbo sont revenues.' });
    }
}

context.set('st', st, 'file');
const active = [];
for (const k in st) {
    if (st[k] && st[k].active && st[k].label) { active.push(st[k].label); }
}
global.set('haku_active_alerts', active);
if (out.length) {
    node.status({ fill: 'red', shape: 'dot', text: out[out.length - 1].subject });
    out.forEach(a => node.send({ key: a.key, subject: a.subject, body: a.body, payload: a.subject }));
}
return null;

// Prepare : 1) la commande shell (arguments proteges par quotes simples)
//           2) la notification dashboard.
const q = s => "'" + String(s).replace(/'/g, "'\\''") + "'";
const subject = msg.subject || 'Haku : alerte';
const body = msg.body || '';
return [
    { payload: ' ' + q(subject) + ' ' + q(body) },
    { payload: subject + ' - ' + body }
];

// Trace le code retour de send-alert.sh (0 = OK ou SMTP non configure).
const rc = msg.payload && msg.payload.code;
if (rc !== 0) { node.warn('send-alert.sh : code retour ' + rc + ' (voir journalctl)'); }
return null;

// Alerte 'Pi redemarre' : uniquement si le SYSTEME vient de demarrer
// (uptime < 300 s), pas a chaque simple restart du service nodered.
// msg.payload = sortie de `cut -d. -f1 /proc/uptime` (noeud exec en amont).
const up = parseInt(String(msg.payload).trim(), 10);
if (!isNaN(up) && up >= 300) {
    node.status({ fill: 'grey', shape: 'ring',
                  text: 'restart nodered seul (uptime ' + up + ' s) : pas d alerte' });
    return null;
}
const tz = env.get('TZ') || 'Europe/Paris';
msg.subject = 'Haku : Pi redemarre';
msg.body = 'Le Raspberry Pi du bord a (re)demarre le ' +
    new Date().toLocaleString('fr-FR', { timeZone: tz }) +
    ' (uptime ' + (isNaN(up) ? '?' : up) + ' s).' +
    ' Coupure de courant, watchdog ou reboot planifie du dimanche.';
return msg;

// Test manuel depuis le dashboard (bouton 'Tester l alerte email').
const tz = env.get('TZ') || 'Europe/Paris';
msg.subject = 'Haku : test alerte';
msg.body = 'Ceci est un test manuel envoye depuis le dashboard le ' +
    new Date().toLocaleString('fr-FR', { timeZone: tz }) + '. Tout fonctionne.';
return msg;

// Min/max du jour + integration trapezoidale des Wh solaires.
// Stocke en contexte de flux 'file' (partage avec l'ecriture de 23:55,
// survit au reboot). Remise a zero automatique au changement de date.
const tz = env.get('TZ') || 'Europe/Paris';
const today = new Date().toLocaleDateString('sv-SE', { timeZone: tz }); // AAAA-MM-JJ
const day = flow.get('day', 'file') || {};
if (day.date !== today) {
    day.date = today;
    day.socMin = null; day.socMax = null;
    day.vMin = null; day.vMax = null;
    day.tMin = null; day.tMax = null;
    day.pvWh = 0; day.pvLastTs = null; day.pvLastW = null;
}
const k = msg.topic;
const v = Number(msg.payload);
function mm(minK, maxK) {
    if (day[minK] === null || v < day[minK]) { day[minK] = v; }
    if (day[maxK] === null || v > day[maxK]) { day[maxK] = v; }
}
let outMsg = null;
if (k === 'soc') { mm('socMin', 'socMax'); }
else if (k === 'voltage') { mm('vMin', 'vMax'); }
else if (k === 'temperature') { mm('tMin', 'tMax'); }
else if (k === 'pv_power') {
    const now = Date.now();
    if (day.pvLastTs !== null && day.pvLastW !== null) {
        const dtH = (now - day.pvLastTs) / 3600000;
        if (dtH > 0 && dtH < 0.2) { day.pvWh += ((day.pvLastW + v) / 2) * dtH; }
    }
    day.pvLastTs = now; day.pvLastW = v;
    const wh = Math.round(day.pvWh);
    if (wh !== context.get('lastWhSent')) {
        context.set('lastWhSent', wh);
        outMsg = { payload: wh + ' Wh', topic: 'pv_wh' };
    }
}
flow.set('day', day, 'file');
return outMsg;

// Ecriture de la ligne CSV du jour (23:55). Fichier mensuel : haku-AAAA-MM.csv.
// L'en-tete est ecrit une fois par nouveau fichier (memorise en contexte 'file').
const tz = env.get('TZ') || 'Europe/Paris';
const day = flow.get('day', 'file') || {};
const d = day.date || new Date().toLocaleDateString('sv-SE', { timeZone: tz });
const dir = env.get('JOURNAL_DIR') || '/var/lib/haku/journal';
const filename = dir + '/haku-' + d.slice(0, 7) + '.csv';
const f = x => (x === null || x === undefined) ? '' : String(Math.round(x * 100) / 100);
// v1.1 : compteurs d'evenements flotteurs du jour (enquete fuite lazarette)
const fc = global.get('haku_flood_counts', 'file') || {};
const fcd = (fc.date === d) ? fc : {};
const c = z => String(fcd[z] || 0);
const line = [d, f(day.socMin), f(day.socMax), f(day.vMin), f(day.vMax),
              f(day.tMin), f(day.tMax), String(Math.round(day.pvWh || 0)),
              c('puisard'), c('lazarette'), c('batteries'), c('machine')].join(';');
if (flow.get('journal_file', 'file') !== filename) {
    flow.set('journal_file', filename, 'file');
    node.send({ filename: filename,
        payload: 'date;soc_min;soc_max;v_min;v_max;t_min;t_max;pv_wh;puisard;lazarette;batteries;machine' });
}
node.send({ filename: filename, payload: line });
node.status({ fill: 'green', shape: 'dot', text: 'ecrit : ' + line });
return null;

