const now = Date.now();
const val = (k, maxAgeS) => (sk[k] && (now - sk[k].ts) < (maxAgeS || 30) * 1000) ? sk[k].v : null;
const f1 = v => (v === null) ? null : (Math.round(v * 10) / 10).toString();
const f0 = v => (v === null) ? null : Math.round(v).toString();
const T = '—'; // tiret cadratin
const ang = v => (v === null) ? '' : ' @ ' + Math.round((v + 360) % 360) + '°';

