// Machine a etats de l'enregistreur de traces (tick 10 s).
// Etat persiste dans le context store 'file' -> survit au reboot.
const cfg = {
    startKn: parseFloat(env.get('TRACK_START_KN') || '1.5'),
    startS: parseFloat(env.get('TRACK_START_S') || '120'),
    intervalS: parseFloat(env.get('TRACK_INTERVAL_S') || '60'),
    stopS: parseFloat(env.get('TRACK_STOP_S') || '600')
};
const dir = env.get('TRACKS_DIR') || '/var/lib/haku/tracks';
const now = Date.now();
const sk = global.get('haku_sk') || {};
const pos = (sk.pos && (now - sk.pos.ts) < 30000) ? sk.pos.v : null;
const sog = (sk.sog_kn && (now - sk.sog_kn.ts) < 30000) ? sk.sog_kn.v : null;
let st = context.get('trk', 'file') || { phase: 'idle' };
const pad = x => (x < 10 ? '0' : '') + x;

function gpxOf(points) {
    let s = '<?xml version="1.0" encoding="UTF-8"?>\n' +
        '<gpx version="1.1" creator="Haku Pi" ' +
        'xmlns="http://www.topografix.com/GPX/1/1">\n<trk><name>Haku ' +
        new Date(points[0][2]).toISOString() + '</name><trkseg>\n';
    for (const p of points) {
        s += '<trkpt lat="' + p[0].toFixed(6) + '" lon="' + p[1].toFixed(6) +
             '"><time>' + new Date(p[2]).toISOString() + '</time></trkpt>\n';
    }
    return s + '</trkseg></trk></gpx>\n';
}
function closeTrack(raison) {
    let fileMsg = null;
    let idxMsg = null;
