        const d0 = new Date(st.points[0][2]);
        const name = 'track-' + d0.getUTCFullYear() + pad(d0.getUTCMonth() + 1) +
            pad(d0.getUTCDate()) + '-' + pad(d0.getUTCHours()) +
            pad(d0.getUTCMinutes()) + '.gpx';
        fileMsg = { filename: dir + '/' + name, payload: gpxOf(st.points) };
        idxMsg = { payload: 'reindex' };
