    return [c[0], c[1], { payload: 'Trace close (reprise)' }];
}
if (pos === null || sog === null) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Signal K muet (' + st.phase + ')' });
    return [null, null, { payload: st.phase === 'rec' ? 'NAV (GPS ?)' : 'au repos' }];
}
let tuile = 'au repos';
if (st.phase === 'rec') {
    if (sog >= cfg.startKn) { st.moveTs = now; }
    if (now - (st.lastPtTs || 0) >= cfg.intervalS * 1000 && st.points.length < 6000) {
        st.points.push([pos.lat, pos.lon, now]);
        st.lastPtTs = now;
    }
    tuile = 'NAV : ' + st.points.length + ' pts, SOG ' + sog.toFixed(1) + ' kn';
    node.status({ fill: 'blue', shape: 'dot', text: tuile });
    if ((now - (st.moveTs || now)) >= cfg.stopS * 1000 || st.points.length >= 6000) {
        const c = closeTrack(st.points.length >= 6000 ? 'longueur max' : 'immobilite');
        return [c[0], c[1], { payload: 'Trace close' }];
    }
    context.set('trk', st, 'file');
    return [null, null, { payload: tuile }];
}
if (sog >= cfg.startKn) {
    if (st.phase !== 'arming') { st.phase = 'arming'; st.armTs = now; }
    if (now - st.armTs >= cfg.startS * 1000) {
        st.phase = 'rec';
        st.points = [[pos.lat, pos.lon, now]];
        st.lastPtTs = now;
        st.moveTs = now;
        node.warn('Trace demarree (SOG ' + sog.toFixed(1) + ' kn)');
