// Flotteurs d'envahissement : anti-rebond 3 s, tuiles, alerte email,
// compteur d'evenements par zone pour le CSV quotidien.
// v1.2 : DEUX sources possibles, choisies par WAVESHARE_ENABLED :
//  - 0 : entrees digitales du Cerbo (MQTT digitalinput, comportement v1.1.1
//        strictement inchange) ;
//  - 1 : entrees DI du module Waveshare (FC02, cache global haku_ws_di
//        alimente par l'onglet « 10 - Waveshare Modbus », poll 2 s ;
//        mapping WAVESHARE_DI_*, polarite WAVESHARE_DI_INVERT — contacts NF
//        piques sur les boucles 24 V existantes, a verifier a l'ohmmetre).
// La logique aval (anti-rebond 3 s, alertes email, compteurs CSV) est
// IDENTIQUE quelle que soit la source.
const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
const zones = {
    puisard: String(env.get('DIGITAL_IN_PUISARD') || ''),
    lazarette: String(env.get('DIGITAL_IN_LAZARETTE') || ''),
