    machine: String(env.get('DIGITAL_IN_MACHINE') || '')
};
const wsMap = {
    puisard: String(env.get('WAVESHARE_DI_PUISARD') || ''),
    lazarette: String(env.get('WAVESHARE_DI_LAZARETTE') || ''),
    batteries: String(env.get('WAVESHARE_DI_BATTERIES') || ''),
    machine: String(env.get('WAVESHARE_DI_MACHINE') || '')
};
const cfg = z => (wsOn ? wsMap[z] !== '' : zones[z] !== '');
const noms = { puisard: 'Puisard', lazarette: 'Lazarette',
               batteries: 'Local batteries', machine: 'Salle machine' };
const tz = env.get('TZ') || 'Europe/Paris';
const now = Date.now();
const st = context.get('st', 'file') || {};
const anyConfigured = Object.keys(noms).some(z => cfg(z));

function tuile(z) {
    if (!cfg(z)) { return { topic: z, payload: 'non cable' }; }
    const s = st[z] || {};
    if (s.state === undefined) { return { topic: z, payload: 'attente donnees...' }; }
    const t = s.since ? new Date(s.since).toLocaleString('fr-FR',
        { timeZone: tz, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
    return { topic: z,
        payload: (Number(s.state) === 9 ? 'ALARME EAU' : 'OK') + (t ? ' - depuis ' + t : '') };
}
function setPending(zone, v) {
    const s = st[zone] = st[zone] || {};
    if (s.pending !== v && s.state !== v) {
        s.pending = v;
        s.pendingTs = now;
    } else if (s.state === v) {
        delete s.pending;
        delete s.pendingTs;
    }
}

if (msg.topic === 'tick') {
    // v1.2 : en mode Waveshare la lecture se fait ICI, au tick de 2 s, depuis
    // le cache haku_ws_di — meme anti-rebond de 3 s (2 lectures identiques).
    if (wsOn) {
        const di = global.get('haku_ws_di') || {};
        const inv = String(env.get('WAVESHARE_DI_INVERT') || '0') === '1';
        if (Array.isArray(di.bits) && (now - (di.ts || 0)) < 15000) {
            for (const z in noms) {
                if (!cfg(z)) { continue; }
                const n = parseInt(wsMap[z], 10);
                if (isNaN(n) || n < 1 || n > di.bits.length) { continue; }
                let raw = di.bits[n - 1] === true;
                if (inv) { raw = !raw; }
                setPending(z, raw ? 9 : 8);   // meme convention interne 9=Alarme / 8=OK
            }
        }
    }
    // Plusieurs zones peuvent changer dans le MEME tick (voies d'eau
    // simultanees) : on ACCUMULE alertes et notifications, chacune part.
    const alertes = [];
    const notifs = [];
    let changed = false;
    const today = new Date().toLocaleDateString('sv-SE', { timeZone: tz });
    for (const z in zones) {
        const s = st[z];
        if (!s || s.pending === undefined || (now - s.pendingTs) < 3000) { continue; }
        if (s.pending !== s.state) {
            const prev = s.state;
            s.state = s.pending;
            s.since = now;
            changed = true;
            const fc = global.get('haku_flood_counts', 'file') || {};
            if (fc.date !== today) {
                fc.date = today; fc.puisard = 0; fc.lazarette = 0;
                fc.batteries = 0; fc.machine = 0;
            }
            fc[z] = (fc[z] || 0) + 1;
            global.set('haku_flood_counts', fc, 'file');
            if (Number(s.state) === 9) {
                alertes.push({ subject: 'Haku : EAU DANS ' + noms[z].toUpperCase(),
                    body: 'Flotteur "' + noms[z] + '" en ALARME (' +
                          (wsOn ? 'entree DI Waveshare' : 'entree digitale Cerbo') + '). ' +
                          'Verifier immediatement - pompe de cale / voie d eau.' });
            } else if (Number(prev) === 9) {
