    for (const a of alertes) { node.send([null, a, null, null]); }
    for (const nf of notifs) { node.send([null, null, null, nf]); }
    // Premiere execution : masquer les groupes (pages Bord ET Surveillance)
    // si AUCUN flotteur n'est configure, quelle que soit la source.
    if (!context.get('ctlSent')) {
        context.set('ctlSent', true);
        if (!anyConfigured) {
            return [null, null, { payload: { groups: { hide:
                ['Bord:Envahissement', 'Surveillance:Eau dans les cales'] } } }, null];
        }
    }
    return null;
}
// Message MQTT digitalinput (source v1.1) — ignore si la source est Waveshare
if (wsOn) { return null; }
const t = String(msg.topic).split('/');
if (t.length >= 5 && t[2] === 'digitalinput') {
    const inst = t[3];
    let zone = null;
    for (const z in zones) { if (zones[z] !== '' && zones[z] === inst) { zone = z; } }
    if (zone) {
        let v = null;
        try {
            const p = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
            v = Number(p.value);
        } catch (e) { v = null; }
        if (v !== null) {
            setPending(zone, v);
            context.set('st', st, 'file');
        }
    }
}
return null;

// Interrupteur Instruments : ON = ALIMENTER le circuit, OFF = le couper.
// v1.3 — tient compte du contact physiquement utilise sur le module :
//   WAVESHARE_INSTR_CONTACT = 'NC' (defaut) -> bobine au repos = circuit ALIMENTE
//   WAVESHARE_INSTR_CONTACT = 'NO'          -> bobine au repos = circuit COUPE
// 'value' envoye au module = etat de la BOBINE, jamais celui du circuit.
const want = (msg.payload === true || msg.payload === 'true' || msg.payload === 'ON' || msg.payload === 1);
const desired = want ? 1 : 0;                       // etat voulu du CIRCUIT
const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
const nc = String(env.get('WAVESHARE_INSTR_CONTACT') || 'NO').toUpperCase() === 'NC';
if (wsOn) {
    const n = parseInt(env.get('WAVESHARE_INSTR_RELAY') || '1', 10);
    const coil = nc ? (desired ? 0 : 1) : desired;
    node.status({ fill: desired ? 'green' : 'grey', shape: 'dot',
                  text: 'instruments ' + (desired ? 'ALIMENTES' : 'coupes') + ' (CH' + n + ' ' + (nc ? 'NC' : 'NO') + ', bobine ' + coil + ')' });
    return [null,
            { payload: 'Alimentation instruments ' + (desired ? 'ALLUMEE' : 'coupee') + ' (Waveshare CH' + n + ')' },
            { payload: (desired ? 'ON' : 'OFF') },
            { topic: 'relay_cmd', payload: { relay: n, value: coil } }];
}
const portal = global.get('haku_portal_id', 'file');
if (!portal) { return [null, { payload: 'Cerbo non decouvert : commande impossible' }, null, null]; }
const idx = String(env.get('INSTR_RELAY_INDEX') || '1');
node.status({ fill: desired ? 'green' : 'grey', shape: 'dot', text: 'instruments (Cerbo) -> ' + (desired ? 'ON' : 'OFF') });
return [ { topic: 'W/' + portal + '/system/0/Relay/' + idx + '/State', payload: JSON.stringify({ value: desired }) },
         { payload: 'Alimentation instruments ' + (desired ? 'ALLUMEE' : 'coupee') },
         { payload: (desired ? 'ON' : 'OFF') }, null ];

// Etat instruments affiche = readback REEL :
//  - WAVESHARE_ENABLED=1 : lecture FC01 du relais WAVESHARE_INSTR_RELAY
//    (evenements 'ws_coils' de l'onglet 10) ;
//  - sinon (v1.1) : readback MQTT du relais Cerbo (cle relay_instr).
const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
if (msg.topic === 'ws_coils') {
    if (!wsOn) { return null; }
    const n = parseInt(env.get('WAVESHARE_INSTR_RELAY') || '1', 10);
    const bits = msg.payload;
    if (!Array.isArray(bits) || bits[n - 1] === undefined) { return null; }
    const nc = String(env.get('WAVESHARE_INSTR_CONTACT') || 'NO').toUpperCase() === 'NC';
    const circuitOn = nc ? !bits[n - 1] : !!bits[n - 1];
    return { payload: circuitOn ? 'ON' : 'OFF' };
}
if (msg.topic !== 'relay_instr' || wsOn) { return null; }
return { payload: Number(msg.payload) === 1 ? 'ON' : 'OFF' };

// Champ "nom du prochain port" (vide = nom automatique).
flow.set('port_name', String(msg.payload || '').trim());
return null;

// Bouton "Declarer ce port" : memorise la position actuelle.
const sk = global.get('haku_sk') || {};
const now = Date.now();
if (!sk.pos || (now - sk.pos.ts) > 120000) {
    return [null, { payload: 'Position GPS inconnue : port non declare' }, null];
}
const lat = sk.pos.v.lat;
const lon = sk.pos.v.lon;
let name = String(flow.get('port_name') || '').trim();
if (!name) {
    name = 'Port ' + Math.abs(lat).toFixed(3) + (lat >= 0 ? 'N' : 'S') + ' ' +
           Math.abs(lon).toFixed(3) + (lon >= 0 ? 'E' : 'O');
}
const ports = global.get('haku_ports', 'file') || [];
ports.push({ nom: name, lat: lat, lon: lon, declare_ts: new Date().toISOString() });
global.set('haku_ports', ports, 'file');
flow.set('port_name', '');
node.status({ fill: 'green', shape: 'dot', text: name });
// Ecriture ATOMIQUE : fichier temporaire puis mv -f (rename) par le noeud
// exec en aval -> pas de ports.json corrompu sur coupure de courant.
return [
    { filename: '/var/lib/haku/ports.json.tmp', payload: JSON.stringify(ports, null, 1) },
    { payload: 'Port declare : ' + name + ' (' + ports.length + ' au total)' },
    { payload: '' }
];

// Au demarrage : si le contexte est vide (premiere installation ou
// restauration), recharge les ports depuis /var/lib/haku/ports.json.
const cur = global.get('haku_ports', 'file');
if (Array.isArray(cur) && cur.length) {
    node.status({ fill: 'green', shape: 'dot', text: cur.length + ' port(s) (contexte)' });
    return null;
}
let ports = [];
try {
    const parsed = JSON.parse(msg.payload);
    if (Array.isArray(parsed)) { ports = parsed; }
} catch (e) { /* fichier vide ou absent : normal au premier boot */ }
global.set('haku_ports', ports, 'file');
node.status({ fill: 'green', shape: 'dot', text: ports.length + ' port(s) (fichier)' });
return null;

// Geofence (tick 60 s) — PRIMAUTE COLREG (regle 30) : ce flux n'ETEINT
// JAMAIS le feu de mouillage automatiquement. A l'entree dans le rayon
// GEOFENCE_M d'un port declare :
//   - mode MOUILLAGE (pose manuellement) -> AUCUNE bascule, notification
//     rappelant de passer en MARINA a la main si on est au ponton ;
//   - mode deja MARINA -> rien.
// Alerte "position anormale" si le bateau s'ecarte de plus de
// GEOFENCE_ALERT_M du port en mode MARINA (derive mouillage/amarres).
const now = Date.now();
const sk = global.get('haku_sk') || {};
const pos = (sk.pos && (now - sk.pos.ts) < 180000) ? sk.pos.v : null;
const ports = global.get('haku_ports', 'file') || [];
const R = parseFloat(env.get('GEOFENCE_M') || '150');
const RA = parseFloat(env.get('GEOFENCE_ALERT_M') || '250');
const st = context.get('gf', 'file') || {};
const T = '—';
if (!ports.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'aucun port declare' });
    return [null, null, null, { payload: 'aucun port declare' }];
}
if (!pos) {
    node.status({ fill: 'grey', shape: 'ring', text: 'position inconnue' });
    return [null, null, null, { payload: T }];
}
function distM(a, b) {
    const rad = Math.PI / 180;
    const dLat = (b.lat - a.lat) * rad;
    const dLon = (b.lon - a.lon) * rad;
    const h = Math.sin(dLat / 2) ** 2 +
        Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLon / 2) ** 2;
    return 6371000 * 2 * Math.asin(Math.min(1, Math.sqrt(h)));
}
let best = null;
let bestD = Infinity;
for (const p of ports) {
    const d = distM(pos, p);
    if (d < bestD) { bestD = d; best = p; }
}
const inside = bestD <= R;
const mode = global.get('haku_mode', 'file') || 'MARINA';
const out = [null, null, null, null];
if (inside && st.insidePort !== best.nom) {
    st.insidePort = best.nom;
    st.alerted = false;
    // PRIMAUTE COLREG : jamais de bascule automatique hors de MOUILLAGE
    // (un feu pose manuellement avant l'arrivee doit RESTER allume).
    if (mode === 'MOUILLAGE') {
        out[2] = { payload: 'Arrivee a "' + best.nom + '" : feu de mouillage ' +
            'TOUJOURS ALLUME la nuit. Passer en MARINA manuellement si au ponton.' };
    }
}
if (!inside && bestD > 2 * RA) { st.insidePort = null; st.alerted = false; }
if (st.insidePort && mode === 'MARINA' && bestD > RA) {
    if (!st.alerted || (now - (st.alertTs || 0)) > 6 * 3600000) {
        st.alerted = true;
        st.alertTs = now;
        out[1] = { subject: 'Haku : POSITION ANORMALE',
            body: 'Le bateau est a ' + Math.round(bestD) + ' m du port declare "' +
                  st.insidePort + '" (seuil ' + RA + ' m) en mode MARINA. ' +
                  'Verifier amarres / mouillage.' };
    }
} else if (st.insidePort && bestD <= R) { st.alerted = false; }
context.set('gf', st, 'file');
const txt = best.nom + ' a ' + (bestD >= 1852 ? (bestD / 1852).toFixed(1) + ' NM' : Math.round(bestD) + ' m');
node.status({ fill: inside ? 'green' : 'grey', shape: 'dot', text: txt });
out[3] = { payload: txt + (inside ? ' (au port)' : '') };
return out;

format:
/* Haku v1.2 - classes de la page Surveillance (maquette v5),
   appliquees via msg.class sur les widgets natifs Dashboard 2.0. */
.sv-zone-ok { background-color: #20301f; border: 1px solid #2c4a2a; border-radius: 10px; }
.sv-zone-ok span { color: #2ec27e; font-weight: 700; }
.sv-zone-alarm { background-color: #3a2020; border: 1px solid #6b2c2c; border-radius: 10px;
                 animation: sv-blink 1.2s linear infinite alternate; }
.sv-zone-alarm span { color: #ff6b6b; font-weight: 800; }
.sv-zone-na { opacity: 0.45; }
.sv-good span { color: #2ec27e; }
.sv-warn span { color: #fab219; }
.sv-crit span { color: #ff6b6b; font-weight: 700; }
.sv-dim { opacity: 0.55; }
@keyframes sv-blink { from { opacity: 1; } to { opacity: 0.55; } }

func:
// Tuiles « Eau dans les cales » de la page Surveillance (maquette v5) :
// SEC (vert) / ALARME EAU (rouge) / non cable, + ligne « dernier evenement ».
// Alimente par les memes messages que les tuiles de la page Bord (sw_flood).
const t = String(msg.topic || '');
const idx = { puisard: 0, lazarette: 1, batteries: 2, machine: 3 }[t];
if (idx === undefined) { return null; }
const p = String(msg.payload || '');
let out;
if (p.indexOf('ALARME') === 0) {
    out = { payload: 'ALARME EAU' + (p.indexOf(' - ') > 0 ? p.slice(p.indexOf(' - ')) : ''),
            class: 'sv-zone-alarm' };
} else if (p.indexOf('OK') === 0) {
    out = { payload: 'SEC', class: 'sv-zone-ok' };
} else if (p.indexOf('non cable') === 0) {
    out = { payload: 'non cable', class: 'sv-zone-na' };
} else {
    out = { payload: '...', class: 'sv-zone-na' };
}
// ligne de synthese : derniere alarme / dernier evenement toutes zones
const st = global.get('haku_flood') || {};
const noms = { puisard: 'Puisard', lazarette: 'Lazarette',
               batteries: 'Local batteries', machine: 'Salle machine' };
let lastZ = null;
for (const z in noms) {
    const s = st[z];
    if (s && s.since && (!lastZ || s.since > st[lastZ].since)) { lastZ = z; }
}
const alarme = Object.keys(noms).some(z => st[z] && Number(st[z].state) === 9);
const tz = env.get('TZ') || 'Europe/Paris';
let resume;
if (alarme) {
    resume = 'ALARME EN COURS — verifier pompes de cale / vannes';
} else if (lastZ) {
    resume = 'Aucune alarme · dernier evenement : ' + noms[lastZ] + ' le ' +
        new Date(st[lastZ].since).toLocaleString('fr-FR', { timeZone: tz,
            day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
} else {
    resume = 'Aucune alarme · aucun evenement enregistre';
}
const msgs = [null, null, null, null,
    { payload: resume, class: alarme ? 'sv-crit' : 'sv-good' }];
msgs[idx] = out;
return msgs;

// Tuiles Batterie de la page Surveillance (tick 5 s) — maquette v5 :
// tension en TRES gros, SOC + courant, ligne d'etat de la derive SOC a quai.
const data = global.get('haku_data') || {};
const now = Date.now();
const val = (k, maxAgeS) => (data[k] && (now - data[k].ts) < (maxAgeS || 300) * 1000)
    ? Number(data[k].v) : null;
const T = '—';
const v = val('voltage');
const soc = val('soc');
const cur = val('current');

// 1. tension en tres gros (fontSize du widget)
const m1 = { payload: v === null ? T : v.toFixed(2) + ' V' };

// 2. SOC + courant signe (convention Victron : >0 = charge)
let sc = (soc === null ? T : Math.round(soc) + ' %');
sc += ' · ' + (cur === null ? T : ((cur > 0 ? '+' : '') + (Math.round(cur * 10) / 10) + ' A'));
const m2 = { payload: sc };

// 3. ligne d'etat de la surveillance a quai (alimentee par fn_soc_drift)
const dr = global.get('haku_soc_drift') || {};
const on = global.get('haku_surv_quai', 'file') === true;
let txt;
let cls = 'sv-good';
if (!on) { txt = 'Surveillance \u00e0 quai d\u00e9sactiv\u00e9e'; cls = 'sv-dim'; }
else if (dr.alert) { txt = 'DERIVE SOC : ' + (dr.txt || ''); cls = 'sv-crit'; }
else if (dr.txt) { txt = dr.txt; }
else { txt = 'Surveillance active (1er echantillon sous 1 h)'; }
return [m1, m2, { payload: txt, class: cls }];

// Persistance du toggle « Surveillance a quai » (meme patron que le mode
// MOUILLAGE/MARINA : context store 'file' — survit au reboot et aux coupures).
const on = (msg.payload === true || msg.payload === 'true' || msg.payload === 'ON');
global.set('haku_surv_quai', on, 'file');
node.status({ fill: on ? 'yellow' : 'grey', shape: 'dot', text: on ? 'active' : 'inactive' });
const notif = (msg.restore === true) ? null
    : { payload: on
        ? 'Surveillance a quai ACTIVE : alerte si le SOC baisse en continu sur ' +
          (env.get('SURV_SOC_H') || '48') + ' h'
        : 'Surveillance a quai desactivee' };
return [{ payload: on }, notif];

// Relit l'etat persiste du toggle « Surveillance a quai » au demarrage.
msg.payload = global.get('haku_surv_quai', 'file') === true;
msg.restore = true;
return msg;

// Alarme « derive SOC a quai » (toutes les heures + au demarrage).
// Quand le toggle « Surveillance a quai » est actif : un echantillon du SOC
// par heure (buffer persiste 'file' — survit au reboot). Si baisse nette
// CONTINUE sur SURV_SOC_H heures (defaut 48) sans remontee (> +1 point entre
// deux echantillons = une charge, qui annule la derive) et d'au moins
// SURV_SOC_DROP points : alerte email « Le bateau perd de la charge a quai »
// via le circuit send-alert existant (rappel ALERT_REMIND_H, retablissement).
const H = parseFloat(env.get('SURV_SOC_H') || '48');
const DROP = parseFloat(env.get('SURV_SOC_DROP') || '5');
const remindH = parseFloat(env.get('ALERT_REMIND_H') || '24');
const now = Date.now();
const on = global.get('haku_surv_quai', 'file') === true;
const st = context.get('soc', 'file') || { hist: [] };

if (!on) {
    if (st.hist.length || st.alerted) { context.set('soc', { hist: [] }, 'file'); }
    global.set('haku_soc_drift', {});
    node.status({ fill: 'grey', shape: 'ring', text: 'surveillance inactive' });
    return null;
}

const data = global.get('haku_data') || {};
const soc = (data.soc && (now - data.soc.ts) < 30 * 60000) ? Number(data.soc.v) : null;
// pas deux echantillons dans la meme demi-heure (cas : reboot + cron)
const lastTs = st.hist.length ? st.hist[st.hist.length - 1].ts : 0;
if (soc !== null && (now - lastTs) > 30 * 60000) {
    st.hist.push({ ts: now, soc: soc });
}
while (st.hist.length && st.hist[0].ts < now - (H + 2) * 3600000) { st.hist.shift(); }

let out = null;
let notif = null;
const first = st.hist.length ? st.hist[0] : null;
const last = st.hist.length ? st.hist[st.hist.length - 1] : null;
let txt = '';
let drift = false;
if (first && last && (last.ts - first.ts) >= (H - 1) * 3600000) {
    // une remontee > +1 point = le chargeur a travaille -> pas de derive
    let rise = false;
    for (let i = 1; i < st.hist.length; i++) {
        if (st.hist[i].soc > st.hist[i - 1].soc + 1) { rise = true; break; }
    }
    const dropPts = first.soc - last.soc;
    drift = (!rise && dropPts >= DROP);
    const span = Math.round((last.ts - first.ts) / 3600000);
    txt = 'SOC ' + Math.round(first.soc) + ' % -> ' + Math.round(last.soc) +
          ' % sur ' + span + ' h';
    if (drift) {
        if (!st.alerted || (now - (st.alertTs || 0)) > remindH * 3600000) {
            st.alerted = true;
            st.alertTs = now;
            out = { subject: 'Haku : le bateau perd de la charge a quai',
                body: 'Baisse continue du SOC sans remontee : ' + txt +
                      ' (seuils : ' + DROP + ' points sur ' + H + ' h). ' +
                      'Chargeur de quai arrete ? Disjoncteur de la borne saute ? ' +
                      'Verifier aussi l entree AC sur le dashboard.' };
            notif = { payload: 'DERIVE SOC A QUAI : ' + txt };
        }
    } else {
        txt += drift ? '' : (dropPts >= 1 ? ' (baisse < seuil)' : ' (pas de derive)');
        if (st.alerted && rise) {
            st.alerted = false;
            out = { subject: 'Haku : la charge a quai est revenue',
                    body: 'Le SOC remonte (' + txt + ') : fin de la derive.' };
            notif = { payload: 'Derive SOC terminee : le SOC remonte' };
        }
    }
} else if (last) {
    const span = first ? Math.round((last.ts - first.ts) / 3600000) : 0;
    txt = 'observation ' + span + ' h/' + H + ' h — SOC ' + Math.round(last.soc) + ' %';
} else {
    txt = 'en attente du SOC (Cerbo)';
}
context.set('soc', st, 'file');
global.set('haku_soc_drift', { alert: st.alerted === true, txt: txt });
node.status({ fill: drift ? 'red' : 'green', shape: 'dot', text: txt || 'attente' });
return [out, notif];

// Vent enregistre 48 h (page Surveillance) — tick 60 s, sur la connexion
// Signal K existante (cache global haku_sk, AUCUNE connexion supplementaire).
// Chaque minute : accumulation du vent (vrai, sinon apparent) + tuile
// « vent actuel ». Toutes les 10 min : un echantillon {moyenne, rafale, baro}
// entre dans le ring buffer 48 h (288 echantillons max, en MEMOIRE) qui est :
//  - persiste sur SD en UNE seule ecriture (meteo48h.json.tmp puis mv
//    atomique — protection SD : <= 1 ecriture / 10 min) ;
//  - rejoue integralement dans le graphe (action replace du ui-chart :
//    robuste au reboot, pas de doublons) ;
//  - compare au seuil WIND_ALERT_KT (alerte email sur la rafale, hysteresis
//    -5 kn, rappel ALERT_REMIND_H, retablissement — circuit send-alert).
const seuil = parseFloat(env.get('WIND_ALERT_KT') || '35');
const remindH = parseFloat(env.get('ALERT_REMIND_H') || '24');
const now = Date.now();
const sk = global.get('haku_sk') || {};
const fresh = (k, s) => (sk[k] && (now - sk[k].ts) < s * 1000) ? sk[k].v : null;
const tws = fresh('tws_kn', 90);
const w = (tws !== null) ? tws : fresh('aws_kn', 90);
const gustNow = fresh('gust_kn', 660);
const f1 = v => (Math.round(v * 10) / 10).toString();

// -- accumulation de la fenetre de 10 min courante ---------------------------
const acc = context.get('acc') || { sum: 0, n: 0, max: 0 };
if (w !== null) {
    acc.sum += w;
    acc.n += 1;
    if (w > acc.max) { acc.max = w; }
    if (gustNow !== null && gustNow > acc.max) { acc.max = gustNow; }
}
context.set('acc', acc);

// -- tuile « vent actuel » (rafraichie chaque minute) ------------------------
let nowTxt = '—';
let nowCls = 'sv-dim';
if (w !== null) {
    nowTxt = f1(w) + ' kn' + (gustNow !== null ? ' · raf. ' + f1(gustNow) : '');
    nowCls = (gustNow !== null && gustNow >= seuil) ? 'sv-crit' : '';
}
const tuileNow = { payload: nowTxt, class: nowCls };

const slot = Math.floor(now / 600000);
const lastSlot = context.get('slot');
context.set('slot', slot);
if (lastSlot === undefined || slot === lastSlot) {
    return [null, null, null, null, tuileNow, null];
}

// ================= nouvelle fenetre de 10 min : echantillon =================
context.set('acc', { sum: 0, n: 0, max: 0 });
const ring = flow.get('meteo48') || [];
const p = fresh('press_hpa', 3600);
if (acc.n > 0) {
    ring.push({ ts: now,
        w: Math.round((acc.sum / acc.n) * 10) / 10,
        g: Math.round(acc.max * 10) / 10,
        p: (p === null) ? null : Math.round(p * 10) / 10 });
}
while (ring.length > 289) { ring.shift(); }
while (ring.length && ring[0].ts < now - 48.5 * 3600000) { ring.shift(); }
flow.set('meteo48', ring);
global.set('haku_meteo_last_ts', ring.length ? ring[ring.length - 1].ts : null);

// -- graphe : replace complet ------------------------------------------------
let chart = null;
if (ring.length) {
    const pts = [];
    for (const s of ring) { pts.push({ x: s.ts, y: s.w, serie: 'moyenne' }); }
    for (const s of ring) { pts.push({ x: s.ts, y: s.g, serie: 'rafales' }); }
    pts.push({ x: ring[0].ts, y: seuil, serie: 'seuil' });
    pts.push({ x: now, y: seuil, serie: 'seuil' });
    chart = { payload: pts };
}

// -- persistance disque : une ecriture / 10 min (tmp puis mv atomique) -------
const fileMsg = ring.length
    ? { filename: '/var/lib/haku/meteo48h.json.tmp', payload: JSON.stringify(ring) }
    : null;

// -- alerte seuil (rafale de l'echantillon de 10 min) ------------------------
const ast = context.get('alert', 'file') || {};
let alertMsg = null;
let notif = null;
const lastS = ring.length ? ring[ring.length - 1] : null;
const g10 = lastS ? lastS.g : null;
if (g10 !== null) {
    if (g10 >= seuil) {
        if (!ast.on || (now - (ast.ts || 0)) > remindH * 3600000) {
            ast.on = true;
            ast.ts = now;
            alertMsg = { subject: 'Haku : VENT FORT — rafales ' + f1(g10) + ' kn',
                body: 'Rafales enregistrees a ' + f1(g10) + ' kn (seuil WIND_ALERT_KT = ' +
                      seuil + ' kn), vent moyen ' + f1(lastS.w) + ' kn sur 10 min. ' +
                      'Verifier amarres / mouillage / annexe / lazy-bag.' };
            notif = { payload: 'VENT FORT : rafales ' + f1(g10) + ' kn (seuil ' + seuil + ' kn)' };
        }
    } else if (ast.on && g10 < seuil - 5) {
        ast.on = false;
        alertMsg = { subject: 'Haku : le vent est retombe (rafales ' + f1(g10) + ' kn)',
            body: 'Rafales redescendues sous ' + (seuil - 5) + ' kn (hysteresis).' };
        notif = { payload: 'Vent retombe : rafales ' + f1(g10) + ' kn' };
    }
}
context.set('alert', ast, 'file');

// -- ligne d'info ------------------------------------------------------------
let info = ring.length
    ? ('graphe 48 h : ' + ring.length + ' echantillons · seuil alerte ' + seuil + ' kn' +
       (p !== null ? ' · baro ' + f1(p) + ' hPa' : ''))
    : 'en attente de donnees vent (Signal K)';
let infoCls = '';
if (ast.on) { info = 'ALERTE VENT active (rafales >= ' + seuil + ' kn) · ' + info; infoCls = 'sv-crit'; }
node.status({ fill: ast.on ? 'red' : 'green', shape: 'dot',
              text: ring.length + ' ech.' + (g10 !== null ? ' · raf ' + f1(g10) + ' kn' : '') });
return [chart, fileMsg, alertMsg, notif, tuileNow, { payload: info, class: infoCls }];

// Recharge le ring buffer meteo 48 h depuis /var/lib/haku/meteo48h.json au
// demarrage (le fichier est ecrit toutes les 10 min par fn_wind_hist), puis
// redessine le graphe. Fichier vide/corrompu -> on repart de zero, sans bruit.
let ring = [];
try {
    const arr = JSON.parse(String(msg.payload || '[]'));
    if (Array.isArray(arr)) {
        const now = Date.now();
        ring = arr.filter(s => s && typeof s.ts === 'number' &&
                               typeof s.w === 'number' && typeof s.g === 'number' &&
                               (now - s.ts) < 49 * 3600000);
    }
} catch (e) { ring = []; }
flow.set('meteo48', ring);
global.set('haku_meteo_last_ts', ring.length ? ring[ring.length - 1].ts : null);
node.status({ fill: 'green', shape: 'dot', text: ring.length + ' echantillons recharges' });
if (!ring.length) { return null; }
const seuil = parseFloat(env.get('WIND_ALERT_KT') || '35');
const pts = [];
for (const s of ring) { pts.push({ x: s.ts, y: s.w, serie: 'moyenne' }); }
for (const s of ring) { pts.push({ x: s.ts, y: s.g, serie: 'rafales' }); }
pts.push({ x: ring[0].ts, y: seuil, serie: 'seuil' });
pts.push({ x: Date.now(), y: seuil, serie: 'seuil' });
return { payload: pts };

// Tuiles « Etat liaison » de la page Surveillance (tick 5 s) :
// quai AC, MQTT Cerbo, age de la derniere donnee, alertes actives.
const data = global.get('haku_data') || {};
const now = Date.now();

// 1. quai AC (1=reseau, 3=quai) — topic absent tant que le Quattro n'est pas pose
let quai = 'n/d (pas de Quattro)';
let qcls = 'sv-dim';
const ac = data.ac_source;
if (ac && (now - ac.ts) < 30 * 60000) {
    const s = Number(ac.v);
    if (s === 1 || s === 3) { quai = 'PRESENT'; qcls = 'sv-good'; }
    else { quai = 'ABSENT (source=' + s + ')'; qcls = 'sv-crit'; }
}

// 2. MQTT Cerbo
const ok = global.get('haku_mqtt_ok') === true;

// 3. age de la derniere donnee MQTT
const last = global.get('haku_last_msg_ts');
let ageTxt = 'aucune donnee recue';
let acls = 'sv-crit';
if (last) {
    const s = Math.round((now - last) / 1000);
    ageTxt = (s < 90) ? ('il y a ' + s + ' s') : ('il y a ' + Math.round(s / 60) + ' min');
    acls = (s < 120) ? 'sv-good' : 'sv-warn';
}

// 4. alertes actives (moteur d'alertes, onglet 4)
const alerts = global.get('haku_active_alerts') || [];
return [
    { payload: quai, class: qcls },
    { payload: ok ? 'connecte' : 'DECONNECTE', class: ok ? 'sv-good' : 'sv-crit' },
    { payload: ageTxt, class: acls },
    { payload: alerts.length ? alerts.join(' | ') : 'Aucune',
      class: alerts.length ? 'sv-warn' : 'sv-good' }
];

// Eclairage exterieur (spreader lights) — RELAIS DU MODULE WAVESHARE.
// Voie : WAVESHARE_LIGHT_RELAY (defaut 2). Etat voulu persiste, re-affirme,
// resynchronise si la lecture FC01 diverge. Minuterie LIGHT_AUTO_OFF_MIN.
// GARDE-FOU : refus si la voie est celle des instruments.
const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
const relay = parseInt(env.get('WAVESHARE_LIGHT_RELAY') || '2', 10);
const instrRelay = parseInt(env.get('WAVESHARE_INSTR_RELAY') || '1', 10);
const autoOff = parseFloat(env.get('LIGHT_AUTO_OFF_MIN') || '0');
const now = Date.now();
const st = context.get('st', 'file') || { on: false };
const isTick = (msg.topic === 'tick');
let notif = null;
if (!isTick) {
    const want = (msg.payload === true || msg.payload === 'true' || msg.payload === 'ON');
    if (!wsOn) {
        return [null, { payload: false }, { payload: 'Eclairage inactif : WAVESHARE_ENABLED=0' }, null];
    }
    if (relay === instrRelay) {
        return [null, { payload: false }, { payload: 'Voie eclairage = voie instruments : commande refusee (haku.env)' }, null];
    }
    st.on = want;
    st.onTs = want ? now : null;
    context.set('st', st, 'file');
    if (msg.restore !== true) {
        notif = { payload: 'Eclairage exterieur ' + (want ? 'ALLUME' : 'eteint') +
                  (want && autoOff > 0 ? ' (extinction auto dans ' + autoOff + ' min)' : '') };
    }
}
if (!wsOn || relay === instrRelay) {
    node.status({ fill: 'grey', shape: 'ring', text: 'inactif' });
    return null;
}
if (st.on && autoOff > 0 && st.onTs && (now - st.onTs) > autoOff * 60000) {
    st.on = false; st.onTs = null;
    context.set('st', st, 'file');
    notif = { payload: 'Eclairage exterieur : extinction automatique (' + autoOff + ' min)' };
}
const nc = String(env.get('WAVESHARE_LIGHT_CONTACT') || 'NO').toUpperCase() === 'NC';
const desired = st.on ? 1 : 0;                      // etat voulu du CIRCUIT
const coilWanted = nc ? (desired ? 0 : 1) : desired; // etat voulu de la BOBINE
const coils = global.get('haku_ws_coils') || {};
const actual = (Array.isArray(coils.bits) && coils.bits[relay - 1] !== undefined)
    ? (coils.bits[relay - 1] ? 1 : 0) : null;
const beat = (context.get('beat') || 0) + 1;
context.set('beat', beat);
const lastSent = context.get('lastSent');
let cmd = null;
if (!isTick || lastSent === undefined || lastSent !== coilWanted || beat % 5 === 0 ||
    (actual !== null && actual !== coilWanted)) {
    context.set('lastSent', coilWanted);
    cmd = { topic: 'relay_cmd', payload: { relay: relay, value: coilWanted } };
}
let etat = st.on ? 'ALLUME' : 'eteint';
if (actual !== null && actual !== coilWanted) { etat += ' - resynchronisation...'; }
if (st.on && autoOff > 0 && st.onTs) {
    const rest = Math.max(0, Math.round(autoOff - (now - st.onTs) / 60000));
    etat += ' (auto-off dans ' + rest + ' min)';
}
node.status({ fill: st.on ? 'yellow' : 'grey', shape: 'dot', text: 'eclairage ' + etat });
const confirm = (!isTick || beat === 1) ? { payload: st.on } : null;
return [null, confirm, notif, cmd];

// ============ Client Modbus TCP minimal — Waveshare Modbus POE ETH Relay (B) ============
// SANS palette tierce : trames MBAP construites a la main, au-dessus du noeud
// « tcp request » natif (mode connexion maintenue). Transactions SEQUENTIELLES
// (une seule en vol), transaction ID verifie, timeout 1,5 s, reconnexion :
//  - FC02 Read Discrete Inputs DI1-8 (poll 2 s)  -> global haku_ws_di
//  - FC01 Read Coils = etat REEL des relais (10 s) -> global haku_ws_coils
//  - FC05 Write Single Coil (commandes + re-affirmations)
// Etats VOULUS des 8 relais persistes (context 'file') — defaut : relais
// instruments (WAVESHARE_INSTR_RELAY) ON car c'est un circuit de NAVIGATION,
// tous les autres OFF. A chaque demarrage de flux et a chaque retour de
// connexion : re-affirmation de TOUS les relais ; a chaque lecture FC01 :
// resynchronisation des relais dont l'etat reel diverge de l'etat voulu.
// Module muet > 5 min -> alerte « module Waveshare injoignable » (meme patron
// que « Cerbo injoignable » : email + tuile + retablissement + rappel).
//
// Entrees (msg.topic)         : 'tick2' (poll DI + timeouts + sante),
//   'tick10' (poll relais), 'relay_cmd' {relay:1..8, value:0|1},
//   payload Buffer (sans topic) = octets recus du module (tcp request).
// Sorties : [1] trame -> tcp request        [2] evenements ws_di / ws_coils
//           [3] alerte email (link)         [4] notification dashboard
//           [5] tuile « Module Waveshare »
const enabled = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
const host = String(env.get('WAVESHARE_HOST') || '');
const unitId = parseInt(env.get('WAVESHARE_UNIT_ID') || '1', 10) & 0xff;
const instrRelay = parseInt(env.get('WAVESHARE_INSTR_RELAY') || '1', 10);
const remindH = parseFloat(env.get('ALERT_REMIND_H') || '24');
const now = Date.now();
const TIMEOUT_MS = 1500;
const OFFLINE_MIN = 5;

if (!enabled || host === '' || host.indexOf('CHANGEME') === 0) {
    if (msg.topic === 'tick10') {
        node.status({ fill: 'grey', shape: 'ring', text: 'WAVESHARE_ENABLED=0 (ou hote vide)' });
        global.set('haku_ws_state', null);
    }
    return null;
}

const st = context.get('mb') || {
    tid: 0, pending: null, queue: [], rx: null,
    up: false, everUp: false, lastOk: 0, timeouts: 0,
    alerted: false, alertTs: 0, needReset: false, bootTs: now
};
// Etats voulus des BOBINES, persistes. v1.3 : dependent du contact utilise.
// Objectif au repos : instruments ALIMENTES, tout le reste eteint.
//  - contact NC -> bobine 0 = circuit alimente  -> defaut 0
//  - contact NO -> bobine 1 = circuit alimente  -> defaut 1
// La cle 'desired_meta' force le recalcul si la configuration des contacts
// change : sans elle, l'ancien etat persiste survivrait a la mise a jour.
const instrNC = String(env.get('WAVESHARE_INSTR_CONTACT') || 'NO').toUpperCase() === 'NC';
const lightNC = String(env.get('WAVESHARE_LIGHT_CONTACT') || 'NO').toUpperCase() === 'NC';
const lightRelay = parseInt(env.get('WAVESHARE_LIGHT_RELAY') || '2', 10);
let desired = context.get('desired', 'file');
let dmeta = context.get('desired_meta', 'file');
if (!desired || !dmeta || dmeta.i !== instrNC || dmeta.l !== lightNC) {
    desired = {};
    for (let i = 1; i <= 8; i++) { desired[i] = 0; }
    desired[instrRelay] = instrNC ? 0 : 1;   // instruments alimentes au repos
    desired[lightRelay] = lightNC ? 1 : 0;   // eclairage eteint au repos
    context.set('desired', desired, 'file');
    context.set('desired_meta', { i: instrNC, l: lightNC }, 'file');
}
global.set('haku_ws_desired', desired);

const out = [null, null, null, null, null];

function buildFrame(fc, addr, val) {
    st.tid = (st.tid + 1) & 0xffff;
    const b = Buffer.alloc(12);
    b.writeUInt16BE(st.tid, 0);   // transaction ID
    b.writeUInt16BE(0, 2);        // protocol ID (0 = Modbus)
    b.writeUInt16BE(6, 4);        // longueur = unit ID + PDU (6 octets)
    b.writeUInt8(unitId, 6);
    b.writeUInt8(fc, 7);
    b.writeUInt16BE(addr, 8);
    b.writeUInt16BE(val, 10);
    return b;
}
function enqueuePoll(fc) {
    // FC de lecture : jamais deux polls identiques en attente
    if (st.queue.some(q => q.fc === fc)) { return; }
    st.queue.push({ fc: fc, addr: 0, val: 8 });
}
function enqueueWrite(relay, on) {
    const addr = relay - 1;
    st.queue = st.queue.filter(q => !(q.fc === 5 && q.addr === addr));
    st.queue.push({ fc: 5, addr: addr, val: on ? 0xFF00 : 0x0000 });
    while (st.queue.length > 24) { st.queue.shift(); }
}
function reaffirmAll(motif) {
    for (let i = 1; i <= 8; i++) { enqueueWrite(i, desired[i] === 1); }
    node.log('Waveshare : re-affirmation des 8 relais (' + motif + ')');
}
function bitsOf(byte) {
    const a = [];
    for (let i = 0; i < 8; i++) { a.push(((byte >> i) & 1) === 1); }
    return a;
}
function markUp() {
    st.lastOk = Date.now();
    st.timeouts = 0;
    if (!st.up) {
        st.up = true;
        reaffirmAll(st.everUp ? 'reconnexion' : 'demarrage du flux');
        if (st.everUp && st.alerted) {
            st.alerted = false;
            out[2] = { subject: 'Haku : module Waveshare de retour',
                body: 'Le module relais/DI Waveshare repond a nouveau en Modbus TCP. ' +
                      'Etats voulus des relais re-affirmes.' };
            out[3] = { payload: 'Module Waveshare : de retour' };
        }
        st.everUp = true;
    }
}

// ---------------- RX : octets du module (possiblement fragmentes) -----------
if (Buffer.isBuffer(msg.payload)) {
    st.rx = st.rx ? Buffer.concat([Buffer.from(st.rx), msg.payload]) : Buffer.from(msg.payload);
    if (st.rx.length > 1024) { st.rx = st.rx.slice(st.rx.length - 64); }
    while (st.rx && st.rx.length >= 8) {
        const len = st.rx.readUInt16BE(4);
        if (len < 2 || len > 250) { st.rx = null; break; }   // flux desynchronise
        const total = 6 + len;
        if (st.rx.length < total) { break; }
        const fr = st.rx.slice(0, total);
        st.rx = st.rx.slice(total);
        const tid = fr.readUInt16BE(0);
        const fc = fr.readUInt8(7);
        if (!st.pending || tid !== st.pending.tid) { continue; }   // reponse orpheline
        const p = st.pending;
        st.pending = null;
        markUp();
        if ((fc & 0x80) !== 0) {
            node.warn('Waveshare : exception Modbus FC' + (fc & 0x7f) +
                      ' code ' + (total >= 9 ? fr.readUInt8(8) : '?'));
            continue;
        }
        if (fc === 2 && p.fc === 2 && total >= 10) {
            const bits = bitsOf(fr.readUInt8(9));
            global.set('haku_ws_di', { ts: Date.now(), bits: bits });
            out[1] = { topic: 'ws_di', payload: bits };
        } else if (fc === 1 && p.fc === 1 && total >= 10) {
            const bits = bitsOf(fr.readUInt8(9));
            global.set('haku_ws_coils', { ts: Date.now(), bits: bits });
            out[1] = { topic: 'ws_coils', payload: bits };
            // resynchronisation : l'etat REEL doit suivre l'etat voulu
            for (let i = 1; i <= 8; i++) {
                if (bits[i - 1] !== (desired[i] === 1)) { enqueueWrite(i, desired[i] === 1); }
            }
        }
        // fc === 5 : echo de confirmation d'ecriture — rien de plus a faire
    }
}

// ---------------- commande de relais (bouton instruments, etc.) -------------
if (msg.topic === 'relay_cmd' && msg.payload &&
    Number(msg.payload.relay) >= 1 && Number(msg.payload.relay) <= 8) {
    const n = Math.round(Number(msg.payload.relay));
    desired[n] = Number(msg.payload.value) ? 1 : 0;
    context.set('desired', desired, 'file');
    global.set('haku_ws_desired', desired);
    enqueueWrite(n, desired[n] === 1);
    enqueuePoll(1);   // relire l'etat reel juste apres
}

// ---------------- ticks ------------------------------------------------------
if (msg.topic === 'tick2') {
    if (st.pending && (now - st.pending.ts) > TIMEOUT_MS) {
        st.pending = null;
        st.timeouts += 1;
        if (st.timeouts >= 2 && st.up) { st.up = false; }
        if (st.timeouts >= 3) { st.needReset = true; st.rx = null; }
    }
    enqueuePoll(2);
    // module injoignable > 5 min (reference : dernier succes, sinon demarrage)
    const ref = st.lastOk || st.bootTs;
    if ((now - ref) > OFFLINE_MIN * 60000) {
        if (!st.alerted || (now - (st.alertTs || 0)) > remindH * 3600000) {
            st.alerted = true;
            st.alertTs = now;
            out[2] = { subject: 'Haku : module Waveshare injoignable',
                body: 'Aucune reponse Modbus TCP du module relais/DI Waveshare (' + host + ':' +
                      String(env.get('WAVESHARE_PORT') || '502') + ') depuis plus de ' +
                      OFFLINE_MIN + ' min. Flotteurs de cale et commande instruments ' +
                      'indisponibles (les DI Cerbo eventuels restent inactifs : source = Waveshare). ' +
                      'Verifier l alimentation 24 V du module (switch-fusible tableau confort) ' +
                      'et le cable Ethernet vers le Pepwave.' };
            out[3] = { payload: 'Module Waveshare INJOIGNABLE (>' + OFFLINE_MIN + ' min)' };
        }
    }
}
if (msg.topic === 'tick10') { enqueuePoll(1); }

// ---------------- emission : une transaction a la fois ----------------------
if (!st.pending && st.queue.length) {
    const q = st.queue.shift();
    const b = buildFrame(q.fc, q.addr, q.val);
    st.pending = { tid: st.tid, fc: q.fc, addr: q.addr, ts: now };
    out[0] = { payload: b };
    if (st.needReset) { out[0].reset = true; st.needReset = false; }
}

context.set('mb', st);
// ---------------- tuile + status --------------------------------------------
let tuileTxt;
if (st.up && st.lastOk) { tuileTxt = 'OK (il y a ' + Math.round((now - st.lastOk) / 1000) + ' s)'; }
else if (st.lastOk) { tuileTxt = 'INJOIGNABLE depuis ' + Math.round((now - st.lastOk) / 60000) + ' min'; }
else { tuileTxt = 'jamais vu depuis le demarrage'; }
if (msg.topic === 'tick10' || out[2] !== null) { out[4] = { payload: tuileTxt }; }
global.set('haku_ws_state', { up: st.up, last_ok_ts: st.lastOk || null,
                              alerted: st.alerted === true });
node.status({ fill: st.up ? 'green' : 'red', shape: 'dot', text: tuileTxt });
return out;

// Node-RED -> InfluxDB SANS palette tierce (tick 60 s) : line protocol
// construit a la main, POST par lots vers l'API HTTP locale /api/v2/write
// via le noeud http request natif. Un point par minute et par serie :
//  - nav   : lat/lon (EN CONTINU : nav, mouillage, port — c'est le traceur),
//            SOG, cap ;
//  - meteo : vent vrai, rafales, vent apparent, baro, sonde, T° air/eau ;
//  - elec  : SOC, V, I, P batterie, T° batterie, solaire W, conso DC W.
// Echec d'ecriture SILENCIEUX avec retry borne : le tampon ne garde jamais
// plus de 15 min de points (protection memoire), une seule requete en vol.
if (String(env.get('INFLUX_ENABLED') || '1') !== '1') {
    node.status({ fill: 'grey', shape: 'ring', text: 'INFLUX_ENABLED=0' });
    return null;
}
const token = String(env.get('INFLUX_TOKEN') || '');
if (!token || token.indexOf('CHANGEME') === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'INFLUX_TOKEN absent (install.sh)' });
    return null;
}
const now = Date.now();
const data = global.get('haku_data') || {};
const sk = global.get('haku_sk') || {};
const fd = (k, s) => (data[k] && (now - data[k].ts) < s * 1000) ? Number(data[k].v) : null;
const fs = (k, s) => (sk[k] && (now - sk[k].ts) < s * 1000) ? sk[k].v : null;
const lines = [];
function line(meas, fields) {
    const parts = [];
    for (const k in fields) {
        const v = fields[k];
        if (v === null || v === undefined || typeof v !== 'number' || isNaN(v)) { continue; }
        parts.push(k + '=' + (Math.round(v * 1000000) / 1000000));
    }
    if (parts.length) { lines.push(meas + ' ' + parts.join(',') + ' ' + now); }
}
const pos = fs('pos', 180);
line('nav', {
    lat: pos ? pos.lat : null,
    lon: pos ? pos.lon : null,
    sog_kn: fs('sog_kn', 180),
    hdg_deg: fs('hdg_deg', 180)
});
line('meteo', {
    tws_kn: fs('tws_kn', 180),
    gust_kn: fs('gust_kn', 660),
    aws_kn: fs('aws_kn', 180),
    press_hpa: fs('press_hpa', 3600),
    depth_m: fs('depth_m', 180),
    temp_air_c: fs('temp_air_c', 600),
    temp_water_c: fs('temp_water_c', 600)
});
line('elec', {
    soc: fd('soc', 300),
    v: fd('voltage', 300),
    i: fd('current', 300),
    p_w: fd('power', 300),
    t_bat_c: fd('temperature', 600),
    pv_w: fd('pv_power', 300),
    dc_w: fd('dc_load', 300)
});
const buf = flow.get('influx_buf') || [];
for (const l of lines) { buf.push({ ts: now, l: l }); }
// borne memoire : rien de plus vieux que 15 min (echec Influx prolonge)
while (buf.length && buf[0].ts < now - 15 * 60000) { buf.shift(); }
flow.set('influx_buf', buf);
global.set('haku_influx_state', { buffered: buf.length,
    errors: flow.get('influx_err') || 0, last_ok_ts: flow.get('influx_ok_ts') || null });
if (!buf.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'aucune donnee fraiche' });
    return null;
}
// une seule requete en vol (le retour est traite par fn_influx_result)
const pend = flow.get('influx_pending');
if (pend && (now - pend) < 30000) { return null; }
flow.set('influx_pending', now);
flow.set('influx_sent', buf.length);
const org = String(env.get('INFLUX_ORG') || 'haku');
const bucket = String(env.get('INFLUX_BUCKET') || 'haku_raw');
const base = String(env.get('INFLUX_URL') || 'http://127.0.0.1:8086');
node.status({ fill: 'blue', shape: 'dot', text: buf.length + ' point(s) -> influx' });
return {
    method: 'POST',
    url: base + '/api/v2/write?org=' + encodeURIComponent(org) +
         '&bucket=' + encodeURIComponent(bucket) + '&precision=ms',
    headers: { 'Authorization': 'Token ' + token,
               'Content-Type': 'text/plain; charset=utf-8' },
    payload: buf.map(x => x.l).join('\n'),
    requestTimeout: 10000
};

// Retour du POST /api/v2/write : 204 = OK -> on retire du tampon ce qui a
// ete envoye ; sinon on GARDE le tampon (retry au prochain tick de 60 s,
// borne a 15 min par fn_influx_sample). Echec volontairement SILENCIEUX :
// pas d'alerte email, juste le statut du noeud et /health.
flow.set('influx_pending', null);
const sent = flow.get('influx_sent') || 0;
const buf = flow.get('influx_buf') || [];
if (msg.statusCode === 204) {
    flow.set('influx_buf', buf.slice(sent));
    flow.set('influx_err', 0);
    flow.set('influx_ok_ts', Date.now());
    node.status({ fill: 'green', shape: 'dot', text: 'ecrit (' + sent + ' pts)' });
} else {
    const err = (flow.get('influx_err') || 0) + 1;
    flow.set('influx_err', err);
    node.status({ fill: 'yellow', shape: 'ring',
                  text: 'echec HTTP ' + (msg.statusCode || '?') + ' (x' + err + ')' });
}
global.set('haku_influx_state', { buffered: (flow.get('influx_buf') || []).length,
    errors: flow.get('influx_err') || 0, last_ok_ts: flow.get('influx_ok_ts') || null });
return null;

// Etat des commandes — v1.4 : la pastille est FUSIONNEE dans le libelle de
// l'interrupteur. Un seul widget par ligne, donc adaptatif sur n'importe quel
// ecran : plus rien a replier.
//
// SECURITE : les 4 interrupteurs ont passthru=false. Un message entrant n'est
// JAMAIS renvoye sur leur sortie — ces mises a jour ne peuvent donc pas
// commander un relais. On renvoie tout de meme l'etat voulu en payload pour
// que l'affichage reste coherent s'il derive.
//
// Lecture INDEPENDANTE de la commande : FC01 du module (etat reel des relais)
// et readback MQTT du relais Cerbo. Une pastille qui refleterait l'ordre
// envoye serait le miroir du bug.
const now = Date.now();
const DEBOUNCE = 60000;
const wsOn = String(env.get('WAVESHARE_ENABLED') || '0') === '1';
const instrRelay = parseInt(env.get('WAVESHARE_INSTR_RELAY') || '1', 10);
const lightRelay = parseInt(env.get('WAVESHARE_LIGHT_RELAY') || '2', 10);
const instrNC = String(env.get('WAVESHARE_INSTR_CONTACT') || 'NO').toUpperCase() === 'NC';
const lightNC = String(env.get('WAVESHARE_LIGHT_CONTACT') || 'NO').toUpperCase() === 'NC';

const coils = global.get('haku_ws_coils') || {};
const bits = Array.isArray(coils.bits) ? coils.bits : null;
const want = global.get('haku_ws_desired') || {};
const wsUp = (global.get('haku_ws_state') || {}).up === true;
const since = context.get('since') || {};

const VERT = '\u{1F7E2}', GRIS = '⚪', ORANGE = '\u{1F7E0}', ROUGE = '\u{1F534}';

function circ(coil, nc) { return nc ? (coil ? 0 : 1) : (coil ? 1 : 0); }

function pastille(key, voulu, reel) {
    if (reel === null) { since[key] = 0; return ORANGE; }
    if (voulu === reel) { since[key] = 0; return reel ? VERT : GRIS; }
    if (!since[key]) { since[key] = now; }
    return (now - since[key] < DEBOUNCE) ? ORANGE : ROUGE;
}

function voie(key, relay, nc) {
    if (!wsOn || !wsUp) { return { dot: ORANGE, on: false }; }
    const voulu = circ(Number(want[relay]) || 0, nc);
    const reel = (bits && bits[relay - 1] !== undefined) ? circ(bits[relay - 1] ? 1 : 0, nc) : null;
    return { dot: pastille(key, voulu, reel), on: voulu === 1 };
}

// --- 1. Feu de mouillage : le Pi observe, il ne commande plus ---
const data = global.get('haku_data') || {};
const relay = (data.relay_state !== undefined) ? Number(data.relay_state.v) : null;
const mode = global.get('haku_mode', 'file') || 'MARINA';
let dotFeu;
if (global.get('haku_mqtt_ok') !== true || relay === null) { dotFeu = ORANGE; }
else { dotFeu = relay === 1 ? VERT : GRIS; }

// --- 2 et 3. Instruments et eclairage ---
const vi = voie('instr', instrRelay, instrNC);
const vl = voie('light', lightRelay, lightNC);

// --- 4. Veille a quai : purement logiciel ---
const quaiOn = global.get('haku_surv_quai', 'file') === true;

context.set('since', since);
node.status({ fill: 'blue', shape: 'dot',
              text: 'feu ' + dotFeu + ' instr ' + vi.dot + ' ecl ' + vl.dot });

const legende = VERT + ' OK, confirmé  ·  ' + GRIS + ' éteint  ·  ' +
                ORANGE + ' en attente ou injoignable  ·  ' +
                ROUGE + ' défaut : commande non confirmée depuis plus de 60 s. ' +
                'Les pastilles reflètent l\'état du relais, pas un forçage manuel.';

return [
    { payload: mode,      ui_update: { label: dotFeu + '  Mooring' } },
    { payload: vi.on,     ui_update: { label: vi.dot + '  Instruments' } },
    { payload: vl.on,     ui_update: { label: vl.dot + '  Spreader' } },
    { payload: quaiOn,    ui_update: { label: (quaiOn ? VERT : GRIS) + '  Veille quai' } },
    { payload: legende }
];

// Sondes Victron (Ruuvi et autres), service MQTT « temperature ».
// Topic : N/<portal>/temperature/<instance>/<Chemin>
// Parsing GENERIQUE : on stocke chaque champ sous son nom de chemin, sans
// presumer de ce que publie le materiel. La vue choisit ce qu'elle sait afficher.
const t = String(msg.topic || '').split('/');
if (t.length < 5 || t[2] !== 'temperature') { return null; }
const inst = t[3];
const champ = t.slice(4).join('/');
const all = global.get('haku_temps') || {};
// payload vide = appareil disparu du bus -> on retire la sonde
if (msg.payload === '' || msg.payload === null) {
    if (champ === 'Temperature') { delete all[inst]; global.set('haku_temps', all); }
    return null;
}
let v;
try {
    const p = (typeof msg.payload === 'object') ? msg.payload : JSON.parse(msg.payload);
    v = p.value;
} catch (e) { return null; }
if (v === null || v === undefined) { return null; }
const s = all[inst] || { inst: inst };
s[champ] = v;
s.ts = Date.now();
all[inst] = s;
global.set('haku_temps', all);
global.set('haku_last_msg_ts', Date.now());
return null;

// Liste des sondes pour la page Environnement.
// Rien n'est invente : un champ absent vaut null, la vue affiche un tiret.
const all = global.get('haku_temps') || {};
const now = Date.now();
const num = (x) => (typeof x === 'number' && isFinite(x)) ? x : null;
const liste = Object.keys(all).sort((a, b) => Number(a) - Number(b)).map((k) => {
    const s = all[k];
    const age = Math.round((now - (s.ts || 0)) / 1000);
    const temp = num(s.Temperature), hum = num(s.Humidity);
    const pres = num(s.Pressure), batt = num(s.BatteryVoltage);
    return {
        id: k,
        nom: s.CustomName || s.ProductName || ('Sonde ' + k),
        temp: (temp === null) ? null : temp.toFixed(1),
        hum: (hum === null) ? null : Math.round(hum),
        press: (pres === null) ? null : Math.round(pres),
        batt: (batt === null) ? null : batt.toFixed(2),
        age: age,
        vieux: age > 900
    };
});
const baro = global.get('haku_baro') || null;
msg.payload = { sondes: liste, baro: baro };
node.status({ fill: liste.length ? 'green' : 'grey', shape: 'dot', text: liste.length + ' sonde(s)' });
return msg;

// Alertes des sondes d'environnement : temperatures et chute de pression.
// Se branche sur la chaine d'alertes existante (subject/body -> lnk_in_ext_alerts),
// donc memes e-mails, memes notifications, meme rappel que les autres alertes.
const now = Date.now();
const all = global.get('haku_temps') || {};
const remindH = parseFloat(env.get('ALERT_REMIND_H') || '24');
const delaiMs = parseFloat(env.get('TEMP_ALERT_DELAY_MIN') || '30') * 60000;
const quai = global.get('haku_surv_quai', 'file') === true;

// Regles surchargeables par TEMP_ALERT_RULES (JSON). 'match' = fragment du nom
// de la sonde, insensible a la casse. 'maxQuai' s'applique quand la surveillance
// a quai est active : bateau inoccupe, moteur froid, on peut serrer le seuil.
let regles;
try { regles = JSON.parse(env.get('TEMP_ALERT_RULES') || ''); } catch (e) { regles = null; }
if (!Array.isArray(regles) || regles.length === 0) {
    regles = [
        { match: 'engine',      max: 60, maxQuai: 45 },
        { match: 'freezer',     max: -10 },
        { match: 'fridge down', max: 14 }
    ];
}

const st = context.get('st', 'file') || {};
if (!st.temps) { st.temps = {}; }
if (!Array.isArray(st.baro)) { st.baro = []; }
const out = [];

// ---------- Temperatures ----------
for (const k in all) {
    const s = all[k];
    const nom = s.CustomName || s.ProductName || ('Sonde ' + k);
    const t = s.Temperature;
    if (typeof t !== 'number' || !isFinite(t)) { continue; }
    const r = regles.find((x) => nom.toLowerCase().indexOf(String(x.match).toLowerCase()) !== -1);
    if (!r) { continue; }
    const seuil = (quai && typeof r.maxQuai === 'number') ? r.maxQuai : r.max;
    if (typeof seuil !== 'number') { continue; }
    const e = st.temps[k] || { depuis: 0, alerte: false, ts: 0 };
    if (t > seuil) {
        if (!e.depuis) { e.depuis = now; }
        const tenu = now - e.depuis;
        // le depassement doit durer : absorbe ouvertures de porte et degivrages
        if (tenu >= delaiMs && (!e.alerte || (now - e.ts) > remindH * 3600000)) {
            e.alerte = true; e.ts = now;
            out.push({ subject: 'Haku : ' + nom + ' - temperature anormale',
                       body: nom + ' est a ' + t.toFixed(1) + ' C depuis ' + Math.round(tenu / 60000) +
                             ' min. Seuil : ' + seuil + ' C' +
                             ((quai && typeof r.maxQuai === 'number') ? ' (mode surveillance a quai)' : '') + '.' });
        }
    } else if (t < seuil - 2) {   // hysteresis de 2 C avant de rearmer
        if (e.alerte) {
            out.push({ subject: 'Haku : ' + nom + ' - retour a la normale',
                       body: nom + ' est redescendue a ' + t.toFixed(1) + ' C (seuil ' + seuil + ' C).' });
        }
        e.depuis = 0; e.alerte = false;
    }
    st.temps[k] = e;
}

// ---------- Pression : mediane des sondes qui la publient ----------
// La mediane evite de dependre d'une sonde particuliere et resiste a une valeur
// aberrante. Ce n'est pas la valeur absolue qui annonce le mauvais temps, c'est
// la VITESSE de chute : -3 hPa/3 h = coup de vent, -5 hPa/3 h = tempete.
const pres = Object.keys(all).map((k) => all[k].Pressure)
    .filter((v) => typeof v === 'number' && isFinite(v) && v > 800 && v < 1100)
    .sort((a, b) => a - b);
if (pres.length) {
    const med = pres[Math.floor(pres.length / 2)];
    st.baro.push({ t: now, p: med });
    st.baro = st.baro.filter((x) => now - x.t <= 3.5 * 3600000);
    const vieux = st.baro.filter((x) => now - x.t >= 2.75 * 3600000);
    if (vieux.length) {
        const delta = med - vieux[0].p;                       // negatif = chute
        const watch = parseFloat(env.get('BARO_DROP_WATCH') || '3');
        const alert = parseFloat(env.get('BARO_DROP_ALERT') || '5');
        let niveau = null;
        if (delta <= -alert) { niveau = 'ALERTE'; }
        else if (delta <= -watch) { niveau = 'vigilance'; }
        if (niveau && (st.baroAlert !== niveau || (now - (st.baroTs || 0)) > remindH * 3600000)) {
            st.baroAlert = niveau; st.baroTs = now;
            out.push({ subject: 'Haku : chute de pression - ' + niveau,
                       body: 'Pression ' + med.toFixed(0) + ' hPa, soit ' + delta.toFixed(1) +
                             ' hPa en 3 h. Reperes : -3 hPa/3 h annonce un coup de vent, ' +
                             '-5 hPa/3 h un creusement rapide. Verifier mouillage et amarrage.' });
        }
        if (delta > -watch && st.baroAlert) {
            out.push({ subject: 'Haku : pression stabilisee',
                       body: 'La chute s\'est arretee : ' + delta.toFixed(1) + ' hPa sur 3 h, ' +
                             med.toFixed(0) + ' hPa.' });
            st.baroAlert = null;
        }
        global.set('haku_baro', { p: med, delta3h: delta, ts: now });
    } else {
        global.set('haku_baro', { p: med, delta3h: null, ts: now });
    }
}

context.set('st', st, 'file');
node.status({ fill: out.length ? 'yellow' : 'green', shape: 'dot',
              text: Object.keys(all).length + ' sonde(s) - ' + st.baro.length + ' pts baro' });
return [out.length ? out : null];
